{
  "title": "The Ruined City Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The party arrives at the ruined royal city.",
      "visual_description": "Crumbling stone walls, broken royal banners flapping in the wind, and an ominous gate ahead.",
      "characters": ["Captain Mara", "Kael the Scout", "Lysa the Mage"]
    },
    {
      "scene_number": 2,
      "caption": "Frightened townspeople warn the group.",
      "visual_description": "Huddled civilians with scared faces point toward the city and whisper about a dragon.",
      "characters": ["Elder Tobias", "Young Finn", "Captain Mara"]
    },
    {
      "scene_number": 3,
      "caption": "The party sneaks through the castle gates.",
      "visual_description": "Massive iron gates partly ajar, rusted hinges, and shadows of armored patrols in the distance.",
      "characters": ["Kael the Scout", "Captain Mara", "Lysa the Mage"]
    },
    {
      "scene_number": 4,
      "caption": "Kael scouts ahead and spots a patrol.",
      "visual_description": "Armored soldiers in tarnished plate mail march in formation past a ruined fountain.",
      "characters": ["Kael the Scout", "Armored Patrol Leader", "Armored Guard"]
    },
    {
      "scene_number": 5,
      "caption": "The group avoids the patrol and enters a cursed tower.",
      "visual_description": "A spiral staircase with glowing runes on the walls, and a heavy door inscribed with warning symbols.",
      "characters": ["Captain Mara", "Kael the Scout", "Lysa the Mage"]
    },
    {
      "scene_number": 6,
      "caption": "Inside the tower, a magical door blocks the way.",
      "visual_description": "A shimmering barrier of blue light with shifting patterns; ancient symbols pulse along the frame.",
      "characters": ["Lysa the Mage", "Captain Mara"]
    },
    {
      "scene_number": 7,
      "caption": "Lysa deciphers the runes and opens the door.",
      "visual_description": "Lysa traces glowing patterns in the air; the barrier flickers and dissolves into sparkling dust.",
      "characters": ["Lysa the Mage", "Kael the Scout", "Captain Mara"]
    },
    {
      "scene_number": 8,
      "caption": "The group discovers a hidden chamber with the captive.",
      "visual_description": "A dim room with chains on the walls, a bound figure in the center, and a single torch flickering.",
      "characters": ["Captain Mara", "Kael the Scout", "Lysa the Mage", "Princess Elara"]
    },
    {
      "scene_number": 9,
      "caption": "They free the princess from her bonds.",
      "visual_description": "Mara cuts the chains with a sword while Kael supports the weakened princess.",
      "characters": ["Captain Mara", "Kael the Scout", "Princess Elara"]
    },
    {
      "scene_number": 10,
      "caption": "Rumors become real as a dragon appears on the tower roof.",
      "visual_description": "Through a broken ceiling, a massive red dragon roars, shaking the tower and sending debris falling.",
      "characters": ["Captain Mara", "Kael the Scout", "Lysa the Mage", "Princess Elara", "Dragon"]
    },
    {
      "scene_number": 11,
      "caption": "The group flees down the tower stairs.",
      "visual_description": "Haste and chaos as they tumble down the spiral stairs, the dragon's roar echoing behind.",
      "characters": ["Captain Mara", "Kael the Scout", "Lysa the Mage", "Princess Elara"]
    },
    {
      "scene_number": 12,
      "caption": "They emerge into a courtyard and face a patrol.",
      "visual_description": "A wide cobblestone square with an armored patrol blocking the path to the main gate.",
      "characters": ["Captain Mara", "Armored Patrol Leader", "Armored Guard", "Kael the Scout", "Lysa the Mage", "Princess Elara"]
    },
    {
      "scene_number": 13,
      "caption": "A brief fight to break through the patrol.",
      "visual_description": "Swords clash, magic flares; Mara parries the leader's blow while Lysa sends a guard flying.",
      "characters": ["Captain Mara", "Armored Patrol Leader", "Armored Guard", "Lysa the Mage", "Kael the Scout"]
    },
    {
      "scene_number": 14,
      "caption": "The group races toward the bridge escape route.",
      "visual_description": "Narrow alleyways, crumbling arches, and a glimpse of a stone bridge ahead over a chasm.",
      "characters": ["Captain Mara", "Kael the Scout", "Lysa the Mage", "Princess Elara"]
    },
    {
      "scene_number": 15,
      "caption": "The dragon lands on the bridge, blocking the exit.",
      "visual_description": "The massive dragon perches on the bridge's midpoint, wings spread, flames licking its jaws.",
      "characters": ["Dragon", "Captain Mara", "Kael the Scout", "Lysa the Mage", "Princess Elara"]
    },
    {
      "scene_number": 16,
      "caption": "Lysa creates a diversion with a magical illusion.",
      "visual_description": "Brilliant illusory phoenix soars toward the dragon, drawing its attention away from the group.",
      "characters": ["Lysa the Mage", "Dragon", "Captain Mara", "Kael the Scout", "Princess Elara"]
    },
    {
      "scene_number": 17,
      "caption": "The group races across the bridge during the distraction.",
      "visual_description": "They sprint over ancient stones, the dragon roaring and turning back as they near the far side.",
      "characters": ["Captain Mara", "Kael the Scout", "Lysa the Mage", "Princess Elara", "Dragon"]
    },
    {
      "scene_number": 18,
      "caption": "The bridge collapses behind them as they escape.",
      "visual_description": "With a final leap to safety, the bridge crumbles into the chasm, the dragon stranded on the far side.",
      "characters": ["Captain Mara", "Kael the Scout", "Lysa the Mage", "Princess Elara", "Dragon"]
    }
  ]
}

